@page "/dashboard"
@rendermode InteractiveServer
@using sv_bbf64ea5cd5a40f591c2eadf07414da4.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.SelectedWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.SelectedWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card @(_lowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 @(_lowStockCount > 5 ? "text-danger" : "text-success")">
                    @_lowStockCount
                </p>
                <p class="text-muted">
                    Items below minimum levels
                    <br />
                    <small>Auto-refreshes every 10 seconds</small>
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p>
                    <span class="badge bg-info">Active</span>
                    Last checked: @_lastChecked.ToString("HH:mm:ss")
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private int _lowStockCount;
    private DateTime _lastChecked = DateTime.Now;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        _alertHandler = () => InvokeAsync(OnAlertUpdated);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await RefreshAlerts();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await RefreshAlerts();
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task RefreshAlerts()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        _lastChecked = DateTime.Now;
        _lowStockCount = count;
        // Notify ALL subscribers (including sidebar badge)
        AlertService.UpdateCount(count);
        StateHasChanged();
    }

    private async Task OnWarehouseChanged()
    {
        // Immediately refresh when warehouse changes
        await RefreshAlerts();
    }

    private void OnAlertUpdated()
    {
        _lowStockCount = AlertService.LastLowStockCount;
        _lastChecked = DateTime.Now;
        StateHasChanged();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

